content.text:
{
  "name": "网页FPV实时画面服务器",
  "name_en": "Web FPV Live View Server",
  "manufacturer": "",
  "description": "一个非实体的软件组件，用于运行基于 Tornado 的网页 FPV 实时画面服务。它主要在实验或移动平台场景中把相机图像通过浏览器页面以实时方式展示，并提供相关的网页控制、校准与视频流接口。",
  "description_en": "A non-physical software component that runs a Tornado-based web FPV live-view service. It is used in lab or mobile-platform workflows to present camera images in real time through a browser, with related web control, calibration, and video streaming endpoints.",
  "actions": [
    {
      "action_name": "auto-update",
      "description": "启动网页服务器。",
      "description_en": "Start the web server."
    },
    {
      "action_name": "auto-run_threaded",
      "description": "在线程化运行模式下更新并提供最新图像帧用于网页实时显示。",
      "description_en": "Update and serve the latest image frame for live web viewing in threaded mode."
    },
    {
      "action_name": "auto-run",
      "description": "在普通运行模式下更新并提供最新图像帧用于网页实时显示。",
      "description_en": "Update and serve the latest image frame for live web viewing in normal mode."
    },
    {
      "action_name": "auto-shutdown",
      "description": "关闭网页服务器。",
      "description_en": "Shut down the web server."
    }
  ],
  "tag_hints": [
    "web FPV",
    "live camera view",
    "browser video streaming",
    "Tornado web server",
    "MJPEG streaming",
    "remote vehicle interface",
    "web calibration page"
  ]
}

